css:
.nutstocks{
 --bg:#f4efe5;
 --paper:#fbf8f1;
 --ink:#17130f;
 --muted:#6b6259;
 --line:#d7ccbc;
 --soft:#ebe2d4;
 --brown:#5d371f;
 --brown2:#8a5b35;
 --green:#43553a;
 --gold:#9b772f;
 --danger:#8c4239;
 --shadow:0 14px 45px rgba(52,34,20,.08);
 --radius:22px;
min-height:100vh;}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
.nutstocks{background:
 radial-gradient(circle at 15% 0%,rgba(155,119,47,.09),transparent 32%),
 linear-gradient(180deg,#f7f2e9 0%,var(--bg) 70%);
 color:var(--ink);
 font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
 line-height:1.45;}
a{color:inherit}
.wrap{width:min(1180px,calc(100% - 34px));margin:auto}
.topbar{
 position:sticky;top:0;z-index:20;
 border-bottom:1px solid rgba(93,55,31,.15);
 background:rgba(247,242,233,.86);backdrop-filter:blur(18px);
}
.nav{height:62px;display:flex;align-items:center;justify-content:space-between;gap:18px}
.brand{display:flex;align-items:center;gap:10px;font-weight:850;letter-spacing:-.03em}
.mark{
 width:34px;height:34px;border-radius:50%;
 background:var(--brown);color:#fff;display:grid;place-items:center;font-size:17px;
 box-shadow:inset 0 0 0 5px rgba(255,255,255,.12)
}
.navlinks{display:flex;gap:18px;color:var(--muted);font-size:13px}
.navlinks a{text-decoration:none}
.hero{padding:88px 0 48px}
.eyebrow{
 display:inline-flex;gap:8px;align-items:center;
 border:1px solid var(--line);background:rgba(255,255,255,.34);
 border-radius:999px;padding:7px 11px;font-size:12px;font-weight:760;letter-spacing:.06em;text-transform:uppercase;color:var(--brown)
}
h1{
 font-family:Georgia,"Times New Roman",serif;
 font-size:clamp(52px,8vw,104px);line-height:.88;letter-spacing:-.065em;
 margin:28px 0 22px;max-width:980px;font-weight:700;
}
.hero p{font-size:clamp(18px,2vw,23px);max-width:790px;color:#4d463f;margin:0}
.hero-grid{display:grid;grid-template-columns:1.5fr .8fr;gap:22px;margin-top:46px}
.statbox,.card,.panel{
 background:rgba(251,248,241,.82);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow)
}
.statbox{padding:24px;display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.stat strong{font-size:33px;letter-spacing:-.04em;display:block}
.stat span{font-size:12px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}
.thesis{padding:25px;background:var(--brown);color:#fff;border-radius:var(--radius);box-shadow:var(--shadow)}
.thesis .kicker{font-size:11px;text-transform:uppercase;letter-spacing:.1em;opacity:.7}
.thesis strong{display:block;font-family:Georgia,serif;font-size:26px;line-height:1.05;margin:12px 0}
section{padding:54px 0}
.section-head{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:22px}
.section-head h2{font-family:Georgia,serif;font-size:42px;letter-spacing:-.045em;margin:0}
.section-head p{margin:0;max-width:560px;color:var(--muted);font-size:14px}
.filters{display:flex;flex-wrap:wrap;gap:8px;margin:19px 0 24px}
.filter{
 border:1px solid var(--line);background:var(--paper);color:var(--muted);
 border-radius:999px;padding:8px 12px;font:inherit;font-size:12px;cursor:pointer
}
.filter.active{background:var(--ink);color:#fff;border-color:var(--ink)}
.stock-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}
.card{padding:20px;transition:.18s ease}
.card:hover{transform:translateY(-3px);box-shadow:0 20px 50px rgba(52,34,20,.12)}
.card-top{display:flex;justify-content:space-between;align-items:flex-start;gap:12px}
.ticker{
 display:inline-flex;border:1px solid var(--line);border-radius:9px;padding:4px 7px;
 font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-weight:800;font-size:12px;background:#fff9
}
.rank{font-size:11px;color:var(--muted)}
.company{font-family:Georgia,serif;font-size:24px;letter-spacing:-.025em;margin:18px 0 5px}
.meta{font-size:12px;color:var(--muted)}
.desc{font-size:14px;margin:16px 0;color:#3f3934;min-height:62px}
.metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px;margin:14px 0 2px}
.metric{border:1px solid var(--line);border-radius:10px;padding:9px 10px;background:rgba(255,255,255,.38)}
.metric b{display:block;font-size:13px;letter-spacing:-.02em}
.metric small{display:block;color:var(--muted);font-size:9px;text-transform:uppercase;letter-spacing:.065em;margin-top:2px}
.purity{display:flex;gap:4px;align-items:center;margin-top:14px}
.dot{width:9px;height:9px;border-radius:50%;border:1px solid var(--brown2);background:transparent}
.dot.on{background:var(--brown2)}
.purity span{margin-left:6px;font-size:11px;color:var(--muted)}
.tags{display:flex;flex-wrap:wrap;gap:6px;margin-top:14px}
.tag{font-size:10px;text-transform:uppercase;letter-spacing:.06em;padding:5px 7px;border-radius:7px;background:var(--soft);color:var(--brown)}
.source{display:inline-block;margin-top:16px;font-size:11px;color:var(--green);text-decoration:none;border-bottom:1px solid currentColor}
.cite{display:inline-flex;align-items:center;gap:4px;margin-left:5px;padding:2px 6px;border:1px solid rgba(67,85,58,.24);border-radius:999px;background:rgba(67,85,58,.06);color:var(--green);font-size:9px;font-weight:750;line-height:1.35;text-decoration:none;white-space:nowrap;vertical-align:1px}
.cite:hover{background:rgba(67,85,58,.12)}
.stat .cite{margin:7px 0 0;font-size:9px}
.metric .cite{margin:6px 0 0;font-size:8px}
.cite-dark{color:#e7c984;border-color:rgba(231,201,132,.28);background:rgba(231,201,132,.08)}
.evidence{margin-top:8px;color:var(--muted);font-size:11px;line-height:1.45}
.evidence strong{color:var(--ink)}
.table-wrap .cite{display:inline-flex;margin:5px 0 0}
.node a{color:inherit;text-decoration:underline;text-decoration-color:rgba(93,55,31,.28);text-underline-offset:2px}
.node a:hover{text-decoration-color:currentColor}
.-note{margin-top:15px;padding:12px 14px;border:1px solid rgba(255,255,255,.14);border-radius:12px;color:#cfc6bb;font-size:11px;max-width:900px}
.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:18px;background:var(--paper)}
table{width:100%;border-collapse:collapse;min-width:850px}
th,td{text-align:left;padding:14px 16px;border-bottom:1px solid var(--line);vertical-align:top}
th{font-size:10px;letter-spacing:.09em;text-transform:uppercase;color:var(--muted);background:#f1e9dc}
td{font-size:13px}
td strong{font-size:14px}
.score{font-family:ui-monospace,monospace}
.chain{
 display:grid;grid-template-columns:repeat(6,1fr);gap:8px;align-items:stretch
}
.node{
 position:relative;background:var(--paper);border:1px solid var(--line);border-radius:16px;padding:18px 14px;min-height:150px
}
.node:not(:last-child):after{
 content:"→";position:absolute;right:-15px;top:50%;transform:translateY(-50%);
 z-index:2;width:22px;height:22px;border-radius:50%;display:grid;place-items:center;background:var(--bg);color:var(--brown)
}
.node b{display:block;font-size:12px;text-transform:uppercase;letter-spacing:.07em;color:var(--brown)}
.node .big{font-family:Georgia,serif;font-size:22px;line-height:1.05;margin:13px 0}
.node small{color:var(--muted)}
.split{display:grid;grid-template-columns:1fr 1fr;gap:18px}
.panel{padding:28px}
.panel h3{font-family:Georgia,serif;font-size:29px;margin:0 0 13px;letter-spacing:-.03em}
.panel p{color:var(--muted);font-size:14px}
.missing{
 padding:34px;border-radius:22px;background:#18140f;color:#fff;position:relative;overflow:hidden
}
.missing:before{
 content:"";position:absolute;width:290px;height:290px;border-radius:50%;right:-120px;top:-120px;
 border:38px solid rgba(255,255,255,.06)
}
.missing .quote{font-family:Georgia,serif;font-size:clamp(31px,4vw,52px);line-height:1.03;letter-spacing:-.045em;max-width:870px;margin:13px 0}
.missing p{max-width:760px;color:#cec7bd}
.missing code{color:#e7c984;font-size:12px}
.callouts{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:15px}
.callout{border:1px solid rgba(255,255,255,.15);border-radius:14px;padding:15px;background:rgba(255,255,255,.04)}
.callout b{display:block;font-size:13px}
.callout span{font-size:11px;color:#bbb2a7}
.sources{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}
.source-row{border-top:1px solid var(--line);padding:13px 0;display:flex;justify-content:space-between;gap:15px;font-size:12px;text-decoration:none}
.source-row span{color:var(--muted)}
.footer{padding:45px 0 70px;color:var(--muted);font-size:11px;border-top:1px solid var(--line);margin-top:25px}
@media(max-width:900px){
 .hero-grid,.split{grid-template-columns:1fr}
 .stock-grid{grid-template-columns:repeat(2,1fr)}
 .chain{grid-template-columns:repeat(2,1fr)}
 .node:not(:last-child):after{display:none}
 .callouts{grid-template-columns:1fr}
}
@media(max-width:620px){
 .navlinks{display:none}
 .hero{padding-top:60px}
 .statbox{grid-template-columns:1fr}
 .stock-grid,.sources{grid-template-columns:1fr}
 .chain{grid-template-columns:1fr}
 .section-head{display:block}
 .section-head p{margin-top:9px}
}

script:
const filters=[...document.querySelectorAll('.filter')];
const cards=[...document.querySelectorAll('.card')];
filters.forEach(btn=>btn.addEventListener('click',()=>{
 filters.forEach(x=>x.classList.remove('active'));
 btn.classList.add('active');
 const f=btn.dataset.filter;
 cards.forEach(c=>{
 const cats=(c.dataset.cat||'').split(' ');
 c.style.display=(f==='all'||cats.includes(f))?'block':'none';
 });
}));
